<?php
require_once __DIR__.'/../../includes/layout.php';require_role(['Admin']);$u=current_user();$scope=work_scope();$requests=rows('SELECT r.* FROM campus_requests r WHERE '.$scope.' AND r.status IN("In review","Returned") ORDER BY r.created_at LIMIT 200');$open=array_filter($requests,fn($r)=>in_array($r['status'],['In review','Returned'],true));$old=array_filter($open,fn($r)=>strtotime($r['created_at'].' UTC')<time()-7*86400);$counts=rows('SELECT o.name,COUNT(r.id) AS pending FROM campus_offices o LEFT JOIN campus_steps s ON s.office_id=o.id AND s.status="Pending" LEFT JOIN campus_requests r ON r.id=s.request_id AND r.status IN("In review","Returned") WHERE '.($u['role']==='Super Admin'?'1=1':'o.reviewer_id='.(int)$u['id']).' GROUP BY o.id ORDER BY pending DESC');$stats=row('SELECT COUNT(*) AS pending,SUM(CASE WHEN r.created_at<datetime("now","-7 days") THEN 1 ELSE 0 END) AS old FROM campus_requests r WHERE '.$scope.' AND r.status IN("In review","Returned")');
$completion=row('SELECT COUNT(*) AS samples,AVG((julianday((SELECT MAX(s.reviewed_at) FROM campus_steps s WHERE s.request_id=r.id))-julianday(r.created_at))*1440) AS minutes FROM campus_requests r WHERE '.$scope.' AND r.status IN("Approved","Resolved")');
render_header('Staff workload'); ?>
<div class="page-title"><div><span class="eyebrow">OFFICE OPERATIONS</span><h1>Staff workload</h1><p>Assigned school workflows and current Registrar/Cashier activity. Counts describe recorded requests, not official service deadlines.</p></div><a class="btn btn-outline-primary" href="/Services/Report">Service analytics</a></div><div class="campus-metrics"><a href="../shared/workflows.php?kind=helpdesk"><strong><?= (int)$stats['pending'] ?></strong>Open workflows</a><a href="#aging"><strong><?= (int)$stats['old'] ?></strong>Open more than seven days</a><?php foreach($counts as $office): ?><a href="#aging"><strong><?= (int)$office['pending'] ?></strong><?= e($office['name']) ?> pending steps</a><?php endforeach; ?></div><section class="panel"><h2>Completed workflow processing time</h2><p><?= $completion['minutes']===null?'No completed samples yet':e(number_format((float)$completion['minutes'],1)).' minutes on average' ?> · <?= (int)$completion['samples'] ?> completed requests</p><p class="small text-muted">Submission to the last office decision, including requester correction time. This is not an official service promise.</p></section><h2>Registrar & Cashier</h2><p data-campus-feed-status role="status">Loading live workload…</p><div class="campus-metrics" data-campus-summary></div><section class="panel" id="aging"><h2>Open workflows by age</h2><?php if(!$open)empty_state('No open workflows');foreach($open as $r): ?><article class="campus-event"><a href="../shared/workflows.php?kind=<?= e($r['kind']) ?>&id=<?= (int)$r['id'] ?>"><?= e($r['reference'].' · '.$r['title']) ?></a><p><?= e($r['status']) ?> · <?= max(0,(int)floor((time()-strtotime($r['created_at'].' UTC'))/86400)) ?> days since submission</p></article><?php endforeach; ?></section><?php render_footer(); ?>
